window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-329c79b3e27b563c"]={"versions": [{"id": "FIG-329c79b3e27b563c", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Strukturelles Artefakt- und Paketierungsmodell (Deployment-/Container-Diagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (UCM – <em>Update and Configuration Management</em>, R18-10 / R1.5.0), funktionale Domäne <em>Over-the-Air</em> (OTA) & Software-Aktualisierung auf Fahrzeugebene (<em>Vehicle Update Management</em>).</li>\n<li><strong>Funktionaler Zweck:</strong> Trennung von Payload-Bereitstellung (<em>Software Packages</em> auf ECU-/SWCL-Ebene) und fahrzeugweiter Orchestrierungs- bzw. Authentisierungsmetadaten (<em>Vehicle Package Manifest Container</em>) zur Gewährleistung von Integrität, Authentizität und Kampagnensteuerung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Software Packages (<code>Software Package A</code>, <code>Software Package B</code>)</p>\n<p class=\"fig-p\">ECU-spezifische Auslieferungseinheiten für Software-Cluster (SWCL):</p>\n<ul class=\"fig-list\">\n<li><strong>Executables:</strong> Kompilierte Binärdateien/Prozesse für die Ziel-POSIX-Laufzeitumgebung.</li>\n<li><strong>Data:</strong> Konfigurations-, Kalibrier- und persistente Nutzdaten.</li>\n<li><strong>Manifests:</strong> Adaptive Core-Manifeste (z. B. <code>ExecutionManifest</code>, <code>ServiceInstanceManifest</code>).</li>\n<li><strong>SWCL Integration arxml:</strong> ARXML-Schnittstellenbeschreibung zur lokalen Integration, Validierung von Abhängigkeiten und Instanziierung auf dem Ziel-Knoten.</li>\n</ul>\n<p class=\"fig-p\">#### Vehicle Package Manifest Container</p>\n<p class=\"fig-p\">Fahrzeugweiter Metadaten- und Sicherheitscontainer, der die Integritätskette schließt:</p>\n<ul class=\"fig-list\">\n<li><strong>Signed container:</strong> Geschützter Bereich, der vor Manipulation durch asymmetrische Kryptografie gesichert ist.</li>\n<li><strong>Vehicle Package manifest:</strong> Zentrale ARXML-Deklaration der fahrzeugweiten Kampagne; definiert Update-Reihenfolgen, globale Vorbedingungen (z. B. Fahrzeug im sicheren Stand / <em>Vehicle State</em>), ECU-Zuordnungen sowie Rollback-Strategien.</li>\n<li><strong>SWCL Package manifest A / B:</strong> Abstrahierte Metadaten und kryptografische Prüfsummen (Hashes) der jeweiligen Einzelpakete (<code>Software Package A/B</code>) zur Sicherstellung von Payload-Konsistenz und Versionierungskompatibilität vor und während der Aktivierung.</li>\n<li><strong>OEM signature:</strong> Digitale Signatur des OEM über den gesamten <code>Signed container</code> (X.509-PKI-basiert). Ermöglicht die dezentrale oder zentrale Verifikation durch den Vehicle Update Manager / UCM Master vor der Verteilung an unterlagerte UCMs.</li>\n</ul>\n<p class=\"fig-p\">#### Relationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>1 : n Aggregation:</strong> Ein <em>Vehicle Package</em> referenziert/steuert $n$ <em>Software Packages</em> (SWCLs), potenziell verteilt über heterogene Adaptive- und Classic-ECUs.</li>\n<li><strong>1 : 1 Kopplung:</strong> Jedes im Payload übertragene <code>Software Package</code> besitzt ein korrespondierendes <code>SWCL Package manifest</code> innerhalb des signierten Containers.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Paket-Empfang & Verifikation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der fahrzeugzentrale Update-Koordinator (UCM Master / VUM) empfängt den <code>Vehicle Package Manifest container</code>.</li>\n<li>Kryptografische Validierung der <code>OEM signature</code> gegen den im Fahrzeug hinterlegten Trust-Anchor (Root-of-Trust/Key-Storage).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Payload-Matching & Validierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abgleich der separaten <code>Software Packages</code> gegen die im Container enthaltenen <code>SWCL Package manifests</code> via SHA-2/SHA-3-Hashabgleich.</li>\n<li>Evaluation fahrzeugweiter Abhängigkeiten und Ziel-Kompatibilitäten anhand des <code>Vehicle Package manifest</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Distribution & Transfer:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Asynchrone Verteilung der <code>Software Packages</code> via UCM-Client-APIs an die Ziel-ECUs (<code>TransferVehiclePackage</code> / <code>TransferSoftwarePackage</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation & Kampagnen-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Koordinierter Aufruf der Phasen <code>Process</code>, <code>Activate</code> und <code>Finish</code> über alle beteiligten UCM-Instanzen unter Berücksichtigung der im <code>Vehicle Package manifest</code> definierten Sicherheitszustände (<em>Safety States</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruch-/Fehlerbehandlung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Validierungsfehler der Signatur oder Hash-Diskrepanzen führen zum sofortigen Abbruch der Kampagne vor dem Flashen/Aktivieren; bei Aktivierungsfehlern greift das koordinierte Rollback auf den vorherigen konsistenten Fahrzeugstand.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Build- & CI/CD-Pipeline:</strong> Die Erstellung von <code>Software Packages</code> kann dezentral (z. B. bei Tier-1-Zulieferern) erfolgen. Die Generierung des <code>Vehicle Package Manifest container</code> sowie die Aufbringung der <code>OEM signature</code> erfordern zwingend Zugriff auf das zentrale OEM-Signatursystem (KMS / HSM).</li>\n<li><strong>Entkopplung von Transfer und Freigabe:</strong> Payloads (<code>Software Packages</code>) können über ungesicherte Pfade oder vorab auf Puffer-Speichern transportiert werden, da die Ausführungs- und Aktivierungsfreigabe strikt an das signierte <code>Vehicle Package manifest</code> gebunden ist.</li>\n<li><strong>ARXML-Konsistenz:</strong> Die <code>SWCL Integration arxml</code> innerhalb des Software-Pakets muss exakt mit den Schnittstellen- und Instanz-Definitionen übereinstimmen, die im globalen <code>SWCL Package manifest</code> referenziert werden; Abweichungen führen zu Validierungsabbrüchen in der Pre-Activation-Phase des UCM.</li>\n</ul>"}, {"id": "FIG-1884ab8836b4645b", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Strukturelles Artefakt- und Paketierungsmodell (Deployment-/Container-Diagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (UCM – <em>Update and Configuration Management</em>), funktionale Domäne <em>Over-the-Air</em> (OTA) & Software-Aktualisierung auf Fahrzeugebene (<em>Vehicle Update Management</em>).</li>\n<li><strong>Funktionaler Zweck:</strong> Zweistufige Strukturierung und Authentifizierung von Software-Aktualisierungen. Trennung von fahrzeugweiter Kampagnensteuerung (<code>Vehicle Package</code>) und modularen, jeweils eigenständig signierten Software-Paketen (<code>Software Package</code>) auf ECU-/Cluster-Ebene.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Software Packages (<code>Software Package A</code>, <code>Software Package B</code>)</p>\n<p class=\"fig-p\">ECU-spezifische, eigenständig geschützte Auslieferungseinheiten:</p>\n<ul class=\"fig-list\">\n<li><strong>Signed container:</strong> Kapselt die Paket-Payload und das Paket-Manifest:</li>\n<li><strong>Executables:</strong> Kompilierte Binärdateien/Prozesse für die Ziel-POSIX-Laufzeitumgebung.</li>\n<li><strong>Data:</strong> Konfigurations-, Kalibrier- und persistente Nutzdaten.</li>\n<li><strong>Manifests:</strong> Adaptive Core-Manifeste (z. B. <code>ExecutionManifest</code>, <code>ServiceInstanceManifest</code>).</li>\n<li><strong>Software Package Manifest:</strong> ARXML-Schnittstellenbeschreibung zur lokalen Integration, Validierung von Abhängigkeiten und Instanziierung auf dem Ziel-Knoten.</li>\n<li><strong>Signature:</strong> Digitale Signatur über den <code>Signed container</code> des jeweiligen Software-Pakets zur Integritäts- und Authentizitätsprüfung auf ECU- oder UCM-Ebene.</li>\n</ul>\n<p class=\"fig-p\">#### Vehicle Package</p>\n<p class=\"fig-p\">Fahrzeugweiter Metadaten- und Sicherheitscontainer zur fahrzeugweiten Kampagnenkoordination:</p>\n<ul class=\"fig-list\">\n<li><strong>Signed container:</strong> Geschützter Bereich, der vor Manipulation gesichert ist:</li>\n<li><strong>Vehicle Package manifest:</strong> Zentrale ARXML-Deklaration der fahrzeugweiten Kampagne; definiert Update-Reihenfolgen, globale Vorbedingungen, ECU-Zuordnungen und Rollback-Strategien.</li>\n<li><strong>Software Package manifest A / B:</strong> Abstrahierte Metadaten und Integritätsreferenzen (z. B. Hashes) der jeweiligen Einzelpakete (<code>Software Package A/B</code>).</li>\n<li><strong>OEM signature:</strong> Digitale Signatur des OEM über den fahrzeugweiten <code>Signed container</code> zur Verifikation vor Verteilung an unterlagerte Einheiten.</li>\n</ul>\n<p class=\"fig-p\">#### Relationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>1 : n Aggregation:</strong> Ein <code>Vehicle Package</code> referenziert und steuert $n$ <code>Software Packages</code>.</li>\n<li><strong>1 : 1 Zuordnung:</strong> Jedes <code>Software Package</code> korrespondiert mit einem <code>Software Package manifest</code> im übergeordneten <code>Vehicle Package</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Paket-Empfang & Verifikation des Vehicle Packages:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der UCM Master empfängt das <code>Vehicle Package</code>.</li>\n<li>Validierung der <code>OEM signature</code> des übergeordneten <code>Signed container</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Payload-Matching & Konsistenzprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abgleich der empfangenen <code>Software Packages</code> gegen die im <code>Vehicle Package</code> enthaltenen <code>Software Package manifests</code>.</li>\n<li>Auswertung der Kampagnenvoraussetzungen anhand des <code>Vehicle Package manifest</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verteilung & Paket-Verifikation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Transfer der <code>Software Packages</code> an die zuständigen UCM-Instanzen.</li>\n<li>Verifikation der spezifischen <code>Signature</code> jedes einzelnen <code>Software Package</code> vor dem Entpacken oder Anwenden.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kampagnen-Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Koordinierte Durchführung der Schritte zur Aktualisierung über die beteiligten Ziel-ECUs hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Spezifikationsbezug:</strong> AUTOSAR Adaptive Platform, Update and Configuration Management (UCM), Spezifikation <em>Platform Design</em>.</li>\n<li><strong>Zweistufige Integritätskette:</strong> Jedes <code>Software Package</code> verfügt über eine eigene <code>Signature</code> über seinen <code>Signed container</code>. Ergänzend dazu sichert die <code>OEM signature</code> das <code>Vehicle Package</code>. Dies ermöglicht die Verifikation einzelner Pakete direkt durch lokale UCMs sowie die Zulieferung signierter Pakete durch Tier-1-Zulieferer.</li>\n<li><strong>Entwickler-Hinweise:</strong></li>\n<li>Der Container auf Software-Package-Ebene bindet das <code>Software Package Manifest</code> fest an Binärdaten und Manifeste.</li>\n<li>Vor der Aktivierung ist sowohl die fahrzeugweite Signatur (<code>OEM signature</code>) als auch die lokale Paketsignatur (<code>Signature</code>) zu prüfen.</li>\n</ul>"}, {"id": "FIG-7a898d9f6ed628b4", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Strukturelles Artefakt- und Paketierungsmodell (Deployment-/Container-Diagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (UCM – <em>Update and Configuration Management</em>), funktionale Domäne <em>Over-the-Air</em> (OTA) & Software-Aktualisierung auf Fahrzeugebene (<em>Vehicle Update Management</em>).</li>\n<li><strong>Funktionaler Zweck:</strong> Zweistufige Strukturierung und Authentifizierung von Software-Aktualisierungen. Trennung von fahrzeugweiter Kampagnensteuerung (<code>Vehicle Package</code>) und modularen, jeweils eigenständig signierten Software-Paketen (<code>Software Package</code>) auf ECU-/Cluster-Ebene.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Software Packages (<code>Software Package A</code>, <code>Software Package B</code>)</p>\n<p class=\"fig-p\">ECU-spezifische, eigenständig geschützte Auslieferungseinheiten:</p>\n<ul class=\"fig-list\">\n<li><strong>Signed container:</strong> Kapselt die Paket-Payload und das Paket-Manifest:</li>\n<li><strong>Executables:</strong> Kompilierte Binärdateien/Prozesse für die Ziel-POSIX-Laufzeitumgebung.</li>\n<li><strong>Data:</strong> Konfigurations-, Kalibrier- und persistente Nutzdaten.</li>\n<li><strong>manifests:</strong> Adaptive Core-Manifeste (z. B. <code>ExecutionManifest</code>, <code>ServiceInstanceManifest</code>).</li>\n<li><strong>Software Package manifest:</strong> ARXML-Schnittstellenbeschreibung zur lokalen Integration, Validierung von Abhängigkeiten und Instanziierung auf dem Ziel-Knoten.</li>\n<li><strong>Authentication tag:</strong> Kryptografisches Authentifizierungselement (z. B. MAC oder digitale Signatur) zur Integritäts- und Authentizitätsprüfung des Pakets.</li>\n</ul>\n<p class=\"fig-p\">#### Vehicle Package</p>\n<p class=\"fig-p\">Fahrzeugweiter Metadaten- und Sicherheitscontainer zur fahrzeugweiten Kampagnenkoordination:</p>\n<ul class=\"fig-list\">\n<li><strong>Signed container:</strong> Geschützter Bereich, der vor Manipulation gesichert ist:</li>\n<li><strong>Vehicle Package manifest:</strong> Zentrale ARXML-Deklaration der fahrzeugweiten Kampagne; definiert Update-Reihenfolgen, globale Vorbedingungen, ECU-Zuordnungen und Rollback-Strategien.</li>\n<li><strong>Software Package manifest A / B:</strong> Abstrahierte Metadaten und Integritätsreferenzen der jeweiligen Einzelpakete (<code>Software Package A/B</code>).</li>\n<li><strong>OEM Authentication tag:</strong> Kryptografisches Authentifizierungselement des OEM über den fahrzeugweiten <code>Signed container</code> zur Verifikation vor der Verteilung.</li>\n</ul>\n<p class=\"fig-p\">#### Relationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>1 : n Aggregation:</strong> Ein <code>Vehicle Package</code> referenziert und steuert $n$ <code>Software Packages</code>.</li>\n<li><strong>1 : 1 Zuordnung:</strong> Jedes <code>Software Package</code> korrespondiert mit einem <code>Software Package manifest</code> im übergeordneten <code>Vehicle Package</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Paket-Empfang & Verifikation des Vehicle Packages:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der UCM Master empfängt das <code>Vehicle Package</code>.</li>\n<li>Validierung des <code>OEM Authentication tag</code> des übergeordneten <code>Signed container</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Payload-Matching & Konsistenzprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abgleich der empfangenen <code>Software Packages</code> gegen die im <code>Vehicle Package</code> enthaltenen <code>Software Package manifests</code>.</li>\n<li>Auswertung der Kampagnenvoraussetzungen anhand des <code>Vehicle Package manifest</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verteilung & Paket-Verifikation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Transfer der <code>Software Packages</code> an die zuständigen UCM-Instanzen.</li>\n<li>Verifikation des spezifischen <code>Authentication tag</code> jedes einzelnen <code>Software Package</code> vor dem Verarbeiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kampagnen-Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Koordinierte Durchführung der Schritte zur Aktualisierung über die beteiligten Ziel-ECUs hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Spezifikationsbezug:</strong> AUTOSAR Adaptive Platform, Update and Configuration Management (UCM), Spezifikation <em>Platform Design</em>.</li>\n<li><strong>Verallgemeinerte Authentifizierung:</strong> Die Sicherheitsabsicherung erfolgt über <code>Authentication tag</code> (Software-Paket-Ebene) und <code>OEM Authentication tag</code> (Vehicle-Package-Ebene). Dadurch werden neben rein asymmetrischen Signaturen auch symmetrische Mechanismen (wie Message Authentication Codes / MAC) oder hybride Authentifizierungsverfahren formal abgedeckt.</li>\n<li><strong>Entwickler-Hinweise:</strong></li>\n<li>Die kryptografische Verifikation muss die durch das Authentifizierungsverfahren spezifizierten Prüfroutinen (z. B. PKI-Signaturprüfung oder Tag-Berechnung via Shared Secret / HSM) implementieren.</li>\n</ul>"}], "trans": [{"from": "FIG-329c79b3e27b563c", "to": "FIG-1884ab8836b4645b", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Software Packages (<code>Software Package A</code>, <code>Software Package B</code>):</strong> Umstellung der internen Struktur auf einen eigenen <code>Signed container</code>, der die Nutzdatenartefakte (<code>Executables</code>, <code>Data</code>, <code>Manifests</code>) sowie ein <code>Software Package Manifest</code> (bisher <code>SWCL Integration arxml</code>) kapselt und durch eine eigene <code>Signature</code> geschützt wird.</li>\n<li><strong>Vehicle Package:</strong> Umbenennung des Gesamtcontainers von <code>Vehicle Package Manifest container</code> zu <code>Vehicle Package</code>.</li>\n<li><strong>Manifest-Referenzen im Vehicle Package:</strong> Umbenennung der manifestbezogenen Kindelemente von <code>SWCL Package manifest A</code> und <code>SWCL Package manifest B</code> zu <code>Software Package manifest A</code> und <code>Software Package manifest B</code>.</li>\n<li><strong>Sicherheitsarchitektur:</strong> Einführung einer zweistufigen Signatur- und Integritätsprüfung (Einzelsignatur auf Software-Package-Ebene ergänzend zur OEM-Signatur auf Vehicle-Package-Ebene).</li>\n</ul>"}, {"from": "FIG-1884ab8836b4645b", "to": "FIG-7a898d9f6ed628b4", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Software Packages (<code>Software Package A</code>, <code>Software Package B</code>):</strong> Ersetzung des Sicherheitselements <code>Signature</code> durch <code>Authentication tag</code>.</li>\n<li><strong>Vehicle Package:</strong> Ersetzung des Sicherheitselements <code>OEM signature</code> durch <code>OEM Authentication tag</code>.</li>\n<li><strong>Kryptografische Verifikation:</strong> Umstellung des Sicherheitsmodells von rein asymmetrischen Signaturen auf generische Authentifizierungsmechanismen (z. B. MAC / symmetrische Tags oder hybride Verfahren).</li>\n</ul>"}]};
